INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'Economics', 'Unit 2', 'Molarum Grade 10 — Economics Unit 2: Theories of Demand and Supply', 'Source-grounded Molarum Grade 10 Economics questions for Unit 2: Theories of Demand and Supply.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('324ba93e-5283-4574-8cd8-cc3a242268d2'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'According to the textbook, demand combines willingness to buy with what other requirement?', 'Ability to pay', 'The textbook states that demand equals willingness to buy plus ability to pay.', 0),('42d7f08b-e1e3-4abe-880e-926b5aac8ef3'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'Why is a person''s desire for a commodity alone not sufficient to count as demand?', 'Demand also requires willingness and ability to pay', 'The source distinguishes demand from desire by requiring willingness and ability to pay.', 1),('2fec2081-9e97-4089-8a4a-17b414dc2ae0'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'What does a demand schedule show?', 'Quantities a consumer is willing to buy at different prices', 'A demand schedule is a table of quantities a consumer is willing to buy at different price levels in a period.', 2),('6673925a-2d84-4ce3-8fc5-d5d70784a37c'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'On the demand curve described in the textbook, which variable is measured on the vertical axis?', 'Price', 'The source identifies price as the independent variable measured on the vertical axis and quantity on the horizontal axis.', 3),('974d9274-1537-4ee3-85a9-a28d0e39831a'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'According to the law of demand, what happens to quantity demanded when a commodity''s price decreases, other things constant?', 'It increases', 'The law of demand states that quantity demanded increases when price decreases, ceteris paribus.', 4),('22510e03-9a04-4780-8604-ed9ddd58671a'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'If the price of coffee rises, what does the textbook say can happen to demand for its substitute, tea?', 'Demand for tea increases', 'Coffee and tea are examples of substitutes, so a rise in one price can increase demand for the other.', 5),('69b55336-db45-462e-8bea-477d5a5dfa82'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'Which pair is identified in the textbook as complementary goods?', 'Tea and sugar', 'The textbook lists tea and sugar as goods used together to satisfy a want.', 6),('978aab0b-188e-431c-898e-6a303fe68944'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'A movement from one point to another on the same demand curve caused by a change in the product''s own price is called what?', 'A change in quantity demanded', 'The source defines movement along a fixed demand curve due to the good''s own price as a change in quantity demanded.', 7),('e61ad2ac-ea87-4090-8351-076655d836e0'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'Which event is described as causing an increase in demand and a rightward shift of the demand curve?', 'An increase in consumer income', 'The demand-shift table states that an increase in income increases demand and shifts the curve rightward.', 8),('7223e62a-6fb4-445a-8222-d98b014f7f51'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'How is market demand derived from individual demand curves according to the textbook?', 'By horizontal summation', 'Market demand is the horizontal sum of individual consumers'' demands at each price.', 9),('1944aefd-450d-46de-8e06-9ed1ca617e0b'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'Which statement best defines supply in the textbook?', 'Amounts a producer is willing and able to produce and offer for sale at given prices', 'Supply is defined as amounts a producer is willing and able to produce and make available for sale over a time period at given prices.', 10),('b2f99611-a740-412b-83f4-fbae6f61d3c7'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'What is the relationship between price and quantity supplied in the law of supply?', 'They are positively related', 'The law of supply states that higher prices lead suppliers to make more available, giving the supply curve a positive slope.', 11),('d652b467-8ad3-4514-8f94-53f53c460b44'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'What causes a movement along an unchanged supply curve?', 'A change in the commodity''s own price', 'The source states that movement along the same supply curve is caused by a change in the good''s own price.', 12),('f584ef03-a0e6-4c9f-8cf9-63c37e07e7ac'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'According to the textbook, what is the likely effect of improved technology on supply?', 'It increases supply', 'Advanced technology increases productivity and increases supply.', 13),('f874309e-6c91-434c-8142-f8f1d0e057cd'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'When is a market in equilibrium?', 'When quantity demanded equals quantity supplied', 'Market equilibrium occurs where quantity demanded equals quantity supplied and the market clears.', 14),('0d805f80-b167-4101-849d-f42232f7d07a'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'What market condition occurs when the price is below the equilibrium intersection of demand and supply?', 'A shortage', 'Below equilibrium, buyers want more while suppliers offer less, producing a shortage.', 15),('1b58a12a-6840-42a9-8b64-7916e72066d4'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'In the shirt schedule, what happens at Birr 25 when quantity supplied is 4 shirts and quantity demanded is 2 shirts?', 'There is a surplus of 2 shirts and price tends to fall', 'At Birr 25, supply exceeds demand by two shirts, creating a surplus that pushes price downward.', 16),('c756edd6-f0b7-42a9-8ea1-1c003c478f28'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'A positive cross elasticity of demand between two goods indicates that they are what?', 'Substitutes', 'The source explains that substitute goods have positive cross elasticity because demand for one moves with the price of the other.', 17),('c47d704a-b43d-4519-8c07-74ade24f6604'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'If a 10% price increase causes quantity demanded to fall by 2%, how does the textbook classify the price elasticity of demand?', 'Inelastic, with absolute coefficient 0.2', 'The textbook''s example gives 0.02 divided by 0.1 as 0.2, which is less than one and therefore inelastic.', 18),('7afd8d03-f934-472e-8070-febb56235d5c'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'multiple_choice', 'How does the textbook compare price elasticity of supply in the long run and short run?', 'Supply is relatively more elastic in the long run', 'The source says suppliers have more time to adjust in the long run, so supply is relatively more elastic.', 19),('1733436c-cd0b-47af-8696-ac3d4ac22ddd'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'true_false', 'Demand requires both willingness to buy and ability to pay.', 'True', 'The textbook defines demand as willingness to buy together with ability to pay.', 20),('58f51cc3-dffd-4b59-81e1-0012b997099b'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'true_false', 'A change in a demand determinant other than the commodity''s own price shifts the demand curve.', 'True', 'The source identifies changes in non-price determinants as causes of demand-curve shifts.', 21),('bdae56b4-7f72-4a03-89ea-c68928fe711d'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'true_false', 'Market supply is derived by summing the quantities supplied by individual suppliers at each possible price.', 'True', 'The textbook derives market supply by summing individual quantities supplied at all possible prices.', 22),('c3634b65-19cf-43c9-8f48-491c889b6877'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'true_false', 'Complementary goods have negative cross elasticity of demand according to the textbook.', 'True', 'When two goods go together, a price increase in one decreases demand for the other, producing negative cross elasticity.', 23),('6a14c246-4fe0-425d-89e6-f6eff312e87c'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'State the textbook definition of demand.', 'The willingness and ability to buy a specific quantity of a commodity at the prevailing price in a given period of time.', 'Demand includes a desire to acquire a commodity together with willingness and ability to pay.', 24),('5b493737-7a11-4833-8b85-b091c176d54b'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'What are the names for downward and upward movement along a fixed demand curve?', 'Downward movement is an extension of demand, and upward movement is a contraction of demand.', 'The source names the two movements along a fixed demand curve as extension and contraction of demand.', 25),('f7686f4a-4c8f-44cf-8193-4f443355b93d'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'How is market demand related to individual demand?', 'Market demand is the horizontal summation of the individual demands of all consumers at each price.', 'The text defines market demand as the total demand of all consumers at a given price over a period.', 26),('3d01cf6a-9a0d-47d3-826a-8532e2b4b59c'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'State the textbook definition of supply.', 'The amounts of a product that a producer is willing and able to produce and make available for sale at given prices over a specific time period, other things constant.', 'Supply concerns what producers are willing and able to offer for sale under stated conditions.', 27),('cc69c146-67c4-4b72-8fa9-66c46b51edfb'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'What makes an equilibrium price a market-clearing price?', 'At the equilibrium price, quantity demanded equals quantity supplied, so the market clears.', 'The textbook calls the price where demand equals supply the market-clearing or equilibrium price.', 28),('a87aa251-be88-45f1-8797-57a9c3827204'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'What is excess supply, and what tendency does it create for price?', 'Excess supply occurs when quantity supplied exceeds quantity demanded, creating a surplus that tends to move price downward.', 'The source links excess supply to a surplus and a downward movement toward equilibrium.', 29),('87574a1e-3280-460a-8af7-f647448c2821'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'Name three factors in the textbook that affect price elasticity of demand.', 'Any three of: nature of the commodity, availability of close substitutes, consumer income, proportion of income spent, urgency of demand, durability, purchase frequency, or time.', 'The textbook lists these factors as determinants of price elasticity of demand.', 30),('ce26ba52-9c38-4a2e-8295-d2282d36853f'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'Distinguish point elasticity of demand from arc elasticity of demand.', 'Point elasticity measures elasticity at a given point or very small price change, while arc elasticity measures average responsiveness over a range of prices.', 'The source defines point elasticity at a point and arc elasticity across an extended range of prices.', 31),('1f96c44f-f08f-4c14-858f-9412f632182f'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'In Amina''s coffee demand schedule, how many kilograms of coffee does she buy at Birr 5 per kilogram?', '8 kg', 'The coffee schedule states that Amina buys 8 kg when the price is Birr 5 per kilogram.', 32),('21c1b70b-c570-470b-820d-cd108cbd816a'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'In the banana demand schedule, what quantity is demanded when the price is Birr 15 per kilogram?', '3 kg', 'The banana schedule gives a quantity demanded of 3 kg at Birr 15 per kilogram.', 33),('75bcc361-98c6-424f-856d-971d3e409f58'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'Using the textbook market demand equation Qm = 5000 - 500P, what is market demand when P = 6?', '2,000', 'Substituting P = 6 gives Qm = 5000 - 500(6) = 2000.', 34),('af7a6bb8-6a9d-4596-8e96-aa9692e684dc'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'For 120 identical potato sellers with Qs = 20p - 5, what market quantity is supplied when p = 4, as shown in the textbook solution?', '9,000 tons', 'The source derives Qm = 2400p - 600 and evaluates it at p = 4 to obtain 9000 tons.', 35),('28a6048f-7538-4686-8f2e-1a0b0eb0bfba'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'In the shirt demand and supply schedule, what is the equilibrium quantity at Birr 20?', '3 shirts', 'At Birr 20, both demand and supply equal 3 shirts in the schedule.', 36),('a46fa458-5158-4a10-801f-e18d3e371411'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'Given Qd = 80 - 3P and Qs = 9P - 40, what is the market-clearing price?', '10 Birr per kg', 'Equating demand and supply gives 80 - 3P = 9P - 40, so 120 = 12P and P = 10 Birr per kg.', 37),('8b6b1e98-ec9c-4358-8f35-48a0e1857d87'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'Using the textbook calculation between points B and C, what is the absolute value of arc price elasticity of demand?', '0.6', 'The worked calculation between B and C gives an absolute arc elasticity value of 0.6.', 38),('41202fb3-62aa-4e7b-8dfa-c56c2ca8bc33'::uuid, '7537cdca-9514-4506-8869-9d02dfcafcf9'::uuid, 'fill_blank', 'In the supply schedule, what quantity is supplied when the price is Birr 78 per kilogram?', '8 kg', 'The supply schedule pairs a price of Birr 78 per kilogram with 8 kg supplied.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('77e93f98-3cf3-4419-8aac-331abeb27c91'::uuid, '324ba93e-5283-4574-8cd8-cc3a242268d2'::uuid, 'Ability to pay', TRUE, 0),('e66823d4-4654-4d17-81b6-11e0d0cbe3b7'::uuid, '324ba93e-5283-4574-8cd8-cc3a242268d2'::uuid, 'A promise to sell', FALSE, 1),('1f9c9d83-dd07-4c70-822b-2b63143dc30a'::uuid, '324ba93e-5283-4574-8cd8-cc3a242268d2'::uuid, 'A government subsidy', FALSE, 2),('42c5185f-8dda-4b70-899e-87b30878fc0b'::uuid, '324ba93e-5283-4574-8cd8-cc3a242268d2'::uuid, 'A large population', FALSE, 3),('9832c6cf-711a-4447-89ad-616b4eda5f92'::uuid, '42d7f08b-e1e3-4abe-880e-926b5aac8ef3'::uuid, 'Demand also requires willingness and ability to pay', TRUE, 0),('80e1bdc5-148d-4380-8814-07446486fe7c'::uuid, '42d7f08b-e1e3-4abe-880e-926b5aac8ef3'::uuid, 'Demand requires the seller to lower the price', FALSE, 1),('e19570c2-5a00-45b2-8e75-f16d0a6b5135'::uuid, '42d7f08b-e1e3-4abe-880e-926b5aac8ef3'::uuid, 'Demand exists only for complementary goods', FALSE, 2),('2aa9ec32-0f2c-49d1-84cf-58f63de4014b'::uuid, '42d7f08b-e1e3-4abe-880e-926b5aac8ef3'::uuid, 'Demand requires a supply curve', FALSE, 3),('b38521a9-1adc-40d8-8f56-6fb2cb34ebc2'::uuid, '2fec2081-9e97-4089-8a4a-17b414dc2ae0'::uuid, 'Quantities a consumer is willing to buy at different prices', TRUE, 0),('647ca8d7-6549-4e22-884f-da85d830323b'::uuid, '2fec2081-9e97-4089-8a4a-17b414dc2ae0'::uuid, 'Costs paid by a producer at different output levels', FALSE, 1),('4d3f8844-6439-4961-868b-90e570a0d5dc'::uuid, '2fec2081-9e97-4089-8a4a-17b414dc2ae0'::uuid, 'Prices of all related goods', FALSE, 2),('9e426def-6773-439a-896e-881635b91ed5'::uuid, '2fec2081-9e97-4089-8a4a-17b414dc2ae0'::uuid, 'A firm''s total revenue over time', FALSE, 3),('633a85fa-db34-4de7-85ce-de594266895b'::uuid, '6673925a-2d84-4ce3-8fc5-d5d70784a37c'::uuid, 'Price', TRUE, 0),('028794c8-5e59-40e5-8c93-f27898080b1e'::uuid, '6673925a-2d84-4ce3-8fc5-d5d70784a37c'::uuid, 'Quantity demanded